custom_css:
/* Aishiteru Theme 1.0.0 | SillyTavern 1.19+ | 0. imports */
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400&family=Manrope:wght@500;600&family=PT+Serif:ital,wght@0,400;0,700;1,400;1,700&family=Prata&display=swap');

/* 0.1 Optional switches. Uncomment only the rule block below a label.
   Optional !important declarations override later state-specific rules;
   switches can be enabled here without moving them. */
/* === MOTION OFF === */
/* MOTION-LIST: sync with section 13 and extension motion.css */
/*
#bg1::before, #bg1::after,
#chat .mes.last_mes, #chat .mes::before, #chat .mes::after,
#chat .mes .swipes-counter::after,
.drawer-content.openDrawer > *,
.popup[opening], .popup[closing], .popup[opening]::backdrop, .popup[closing]::backdrop,
#chat .mes.ds-new,
#top-settings-holder .drawer-icon::before,
dialog.popup::before,
#send_form #mes_stop::after,
#toast-container > div::after,
#chat .mes > .mesAvatarWrapper::after,
#send_but,
#mes_continue,
#options_button,
.popup-button-close,
body #toast-container > div {
    animation: none !important;
}
body *, body *::before, body *::after { transition-duration: 0ms !important; }
body[data-generating="true"] #chat .last_mes:not([is_user="true"])::before { opacity: .8; }
body.ds-theme-active[data-generating="true"] #chat .last_mes > .mesAvatarWrapper::after { content: none; }
#chat .mes:is(.ds-rewinding,.ds-new[is_user="true"])::after { content:none !important; }
#chat .mes > .ds-fx { display:none !important; }
#chat .mes.ds-rewinding .swipes-counter { color:#e6e1f0 !important; }
body :is(.menu_button,.drawer-icon,#send_but,#mes_continue,#options_button,.popup-button-close,.swipe_left,.swipe_right):is(:hover,:active) { transform:none !important; }
*/
/* === GLASS MODE === */
/*
#top-bar, #send_form, .drawer-content.openDrawer {
    backdrop-filter: blur(6px);
}
#bg1::before, #bg1::after { animation: none !important; }
*/
/* === CONTENT-VISIBILITY ===
   Small benefit with ~100 messages; can break bookmark scrollIntoView,
   cause upward scroll jumps and clip shadows. Disabled by default.
#chat .mes:not(.last_mes) {
    content-visibility: auto;
    contain-intrinsic-block-size: auto 160px;
}
*/

/* 1. tokens. SmartTheme values are owned by ST's inline theme settings. */
:root {
    /* Use ST's own block-size token so its chat/drawer offsets stay consistent. */
    /* --ds-tb-rows becomes 2 on narrow phones with 10+ top-bar icons (section 14). */
    --ds-tb-rows: 1;
    --topBarBlockSize: calc(max(40px, calc(var(--topBarIconSize) + var(--topBarBlockPadding))) * var(--ds-tb-rows));
    --mainFontFamily: 'Manrope', 'Segoe UI', sans-serif;
    --monoFontFamily: 'JetBrains Mono', 'Consolas', monospace;
    --ds-reading-font: 'PT Serif', 'Georgia', serif;
    --ds-title-font: 'Prata', 'PT Serif', 'Georgia', serif;
    --ds-bg: #0b0a12;
    --ds-strong: #f7f4fc;
    --ds-muted: #a79fbf;
    --ds-lavender: #a88bff;
    --ds-gold: var(--SmartThemeUnderlineColor);
    --ds-ice: var(--SmartThemeEmColor);
    --ds-crimson: #c2384b;
    --ds-success: #7ed6a8;
    --ds-warning: #e0b45c;
    --ds-error: #ed7b8b;
    --ds-info: #7fb2ff;
    --ds-pink: #f2a7c3;
    --ds-radius-message: 10px;
    --ds-radius-panel: 14px;
    --ds-radius-field: 6px;
    --ds-ease-out: cubic-bezier(.22,1,.36,1);
    --ds-ease-inout: cubic-bezier(.65,0,.35,1);
    --ds-ease-in: cubic-bezier(.55,0,1,.45);
    --ds-ease-rewind: cubic-bezier(.5,0,.2,1);
    --ds-ease-stamp: cubic-bezier(.34,1.45,.64,1);
    --ds-t-xs: 90ms;
    --ds-t-s: 160ms;
    --ds-t-m: 240ms;
    --ds-t-l: 360ms;

--ds-surface-1: #12101c;            /* chat tint solid */
--ds-surface-2: #1a1726;            /* bot message solid */
--ds-surface-3: #221e31;            /* panel solid */
--ds-surface-raised: #2a2540;       /* hover fill on panel items */
/* accent ramps */
--ds-lavender-hi: #bfa8ff;          /* hover text/icon, 7.9:1 on panel */
--ds-lavender-lo: rgba(168,139,255,.14);  /* hover/selected fill */
--ds-gold-hi: #e6c78f;              /* active icon on hover */
--ds-gold-line: rgba(217,178,111,.32);    /* ornament strokes (matches --ds-corner) */
--ds-gold-rule: rgba(217,178,111,.14);    /* inner hairline (existing outline values 0.12–0.16 → unify) */
--ds-crimson-text: #e05a6c;         /* crimson that passes AA as text (4.5:1 on panel) */
--ds-crimson-lo: rgba(194,56,75,.16);     /* destructive hover fill */
--ds-ice-line: rgba(156,195,230,.38);     /* frost ornament strokes */
--ds-shadow-hand: rgba(92,58,140,.35);    /* Witch-shadow tint, edge-only */
/* borders */
--ds-border: var(--SmartThemeBorderColor);   /* #887b98, 4.1:1 on panel = non-text 3:1 OK */
--ds-border-subtle: #3a3352;        /* dividers inside panels, 1.4:1 – decorative only */
--ds-border-strong: #a79fbf;
/* states */
--ds-disabled-fg: #6f6884;          /* 3.1:1 — allowed for disabled only (WCAG exempt) */
--ds-disabled-border: #3a3352;
--ds-focus-ring: var(--ds-lavender);
--ds-focus-width: 2px;
--ds-focus-offset: 3px;
/* frame geometry */
--ds-frame-inset: 4px;              /* inner gilt rule offset (existing outline-offset -4/-5 → -4 everywhere) */
--ds-frame-line: 1px;
--ds-ornament-stroke: .8px;         /* at 1x in ornament SVGs */
--ds-corner-size: 40px;             /* message corner fitting */
--ds-corner-size-panel: 44px;       /* drawer/popup corner fitting */
/* icon */
--ds-icon-size: 20px;               /* inside 40px hit targets */
--ds-icon-size-sm: 16px;            /* message action buttons */
--ds-icon-stroke: 1.75;              /* in 24-unit viewBox */
/* glow */
--ds-glow-lavender: 0 0 0 1px rgba(168,139,255,.55), 0 0 12px rgba(168,139,255,.18);
--ds-glow-gold: 0 0 0 1px rgba(217,178,111,.5), 0 0 10px rgba(217,178,111,.14);
--ds-glow-crimson: 0 0 0 1px rgba(224,90,108,.6), 0 0 12px rgba(194,56,75,.22);
--ds-shadow-panel: 0 8px 24px rgba(0,0,0,.45);

    --reasoning-body-color: var(--SmartThemeBodyColor);
    --reasoning-em-color: var(--SmartThemeEmColor);
    --ds-grain: none; /* ImageGen artwork is supplied by the extension. */
    --ds-clock: none; /* ImageGen artwork is supplied by the extension. */
    --ds-corner: none; /* ImageGen artwork is supplied by the extension. */
    --ds-frost: none; /* ImageGen artwork is supplied by the extension. */
    --ds-seal: none; /* ImageGen artwork is supplied by the extension. */
}

/* 2. base & typography. No changes to ST's moving/resizing geometry. */
body {
    color: var(--SmartThemeBodyColor);
    background-color: var(--ds-bg);
    font-family: var(--mainFontFamily);
    -webkit-font-smoothing: antialiased;
    color-scheme: dark;
}
::selection { background: #51406d; color: #f7f4fc; }
body a { color: var(--ds-lavender); text-underline-offset: .2em; }
body a:hover { text-decoration-thickness: 2px; }
body :is(input, select, textarea) { font-family: var(--mainFontFamily); }
body :is(button, .menu_button, .interactable, input, select, textarea, summary):focus-visible {
    outline: 2px solid var(--ds-lavender);
    outline-offset: 3px;
}
body :is(h1, h2, h3, h4) {
    color: var(--SmartThemeBodyColor);
    font-family: var(--ds-title-font);
    font-weight: 400; /* Prata ships one weight: avoid faux bold */
    letter-spacing: .01em;
    /* break-word, not anywhere: "anywhere" lets flex rows squeeze a heading to one letter per line. */
    overflow-wrap: break-word;
}

/* 3. background. The desktop background-image is always selected by ST. */
#bg1 { overflow: hidden; background-color: var(--ds-bg); box-shadow: inset 0 0 20vmax rgba(11,10,18,.55); }
#bg1::before, #bg1::after {
    content: '';
    position: absolute;
    inset: -4%;
    pointer-events: none;
    background-repeat: no-repeat;
    opacity: .16;
    will-change: auto;
}
#bg1::before {
    background-image: radial-gradient(ellipse at 2% 88%, rgba(68,37,84,.7), transparent 35%), radial-gradient(ellipse at 94% 8%, rgba(100,79,145,.45), transparent 29%);
    animation: none; opacity: .18;
}
#bg1::after {
    background-image: radial-gradient(circle at 8% 20%, #cdb9ff 0 2px, transparent 5px), radial-gradient(circle at 93% 36%, #9cc3e6 0 1px, transparent 4px), radial-gradient(circle at 84% 12%, #d9b26f 0 1px, transparent 4px), radial-gradient(circle at 15% 65%, #cdb9ff 0 1px, transparent 4px);
    opacity: .2; will-change: transform; animation: ds-spirits 150s linear infinite alternate;
}
#chat {
    background-color: var(--SmartThemeChatTintColor);
    background-image: linear-gradient(90deg, transparent, rgba(11,10,18,.16) 50%, transparent);
    color: var(--SmartThemeBodyColor);
    border-inline: 1px solid var(--SmartThemeBorderColor);
    scrollbar-gutter: stable;
    padding-inline: 12px;
}

/* 4. chat & messages. Only last_mes receives an entry animation. */
#chat .mes {
    position: relative;
    background-color: var(--SmartThemeBotMesBlurTintColor);
    border: 1px solid var(--SmartThemeBorderColor);
    outline: none;
    outline-offset: -4px;
    border-radius: var(--ds-radius-message);
    margin-block: 12px;
    padding: 18px 16px;
    box-shadow: none;
    min-width: 0;
}
#chat .mes[is_user="true"] {
    background-color: var(--SmartThemeUserMesBlurTintColor);
    border-inline-start: 3px solid var(--ds-lavender);
}
#chat .mes[is_system="true"], #chat .mes.smallSysMes {
    background-color: var(--SmartThemeChatTintColor);
    border-style: dashed;
    box-shadow: none;
}
#chat .mes.smallSysMes { padding-block: 12px; }
#chat .mes[is_system="true"] .mes_text, #chat .mes.smallSysMes .mes_text {
    font-family: var(--mainFontFamily);
    font-size: max(15px, var(--mainFontSize));
}
#chat .mes.selected { outline: 2px solid var(--ds-lavender); outline-offset: -4px; }
#chat .mes.toolCall { border-inline-start: 3px double var(--ds-gold); }
#chat .mes.ds-new { animation: ds-mes-in var(--ds-t-m) var(--ds-ease-out) backwards; }
#chat .mes::before, #chat .mes::after {
    content: '';
    position: absolute;
    pointer-events: none;
    border-radius: inherit;
    opacity: 0;
}
#chat .mes::before {
    inset: 10px auto 10px 0;
    width: 2px;
    background: var(--ds-gold);
}
#chat .mes::after {
    inset: 0;
    background: linear-gradient(90deg, rgba(194,56,75,.7), transparent 26%, transparent 74%, rgba(194,56,75,.5));
}
body[data-generating="true"] #chat .last_mes:not([is_user="true"])::before {
    opacity: .3; transition: opacity var(--ds-t-s) var(--ds-ease-out);
    animation: ds-generate 2.4s var(--ds-ease-inout) infinite;
}
#chat .mes .ch_name { color: var(--ds-gold); align-items: center; row-gap: 6px; }
#chat .mes .name_text {
    font-family: var(--ds-title-font);
    font-weight: 400; /* Prata ships one weight: avoid faux bold */
    font-size: 1.15em;
    letter-spacing: .01em;
    background: var(--ds-clock) left bottom / 100px 14px no-repeat;
    padding-bottom: 14px;
    overflow-wrap: break-word;
}
#chat .mes :is(.timestamp, .mesIDDisplay, .mes_timer, .tokenCounterDisplay, .mes_ghost) {
    color: var(--ds-muted);
    font-family: var(--mainFontFamily);
    font-size: .8rem;
    opacity: 1;
}
#chat .mes .avatar {
    border: 1px solid var(--ds-gold);
    outline: 1px solid var(--SmartThemeBorderColor);
    outline-offset: 3px;
    background: conic-gradient(from 45deg, #d9b26f, #3a3352, #9cc3e6, #3a3352, #d9b26f);
    box-shadow: inset 0 0 0 2px var(--ds-bg);
}
#chat .mes .avatar img { border-radius: inherit; }
#chat .mes .mes_buttons {
    opacity: 1;
    color: var(--SmartThemeBodyColor);
    transition: opacity 160ms ease;
    gap: 4px;
}
#chat .mes:is(:hover, :focus-within) .mes_buttons { opacity: 1; }
body.expandMessageActions #chat .mes .mes_buttons { opacity: 1; }
/* v2.1: calmer frame — message actions appear on hover/focus where a mouse exists */
@media (hover: hover) {
    #chat .mes .mes_buttons { opacity: 0; }
    #chat .mes:is(:hover, :focus-within) .mes_buttons { opacity: 1; }
}
#chat .mes :is(.mes_button, .mes_edit, .extraMesButtonsHint, .mes_edit_buttons > *) {
    opacity: 1;
    filter: none;
    min-width: 28px;
    min-height: 28px;
    padding: 6px;
    border-radius: var(--ds-radius-field);
    color: var(--SmartThemeBodyColor);
}
#chat .mes :is(.mes_button, .mes_edit, .extraMesButtonsHint, .mes_edit_buttons > *):hover {
    color: var(--ds-lavender);
    background-color: var(--SmartThemeBlurTintColor);
}
#chat .mes textarea {
    color: var(--SmartThemeBodyColor);
    background-color: var(--SmartThemeBlurTintColor);
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: var(--ds-radius-field);
    font-family: var(--ds-reading-font);
    font-weight: 400;
    font-size: max(15px, calc(var(--mainFontSize) * 1.1));
    line-height: 1.65;
    min-height: 12rem;
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
    padding: 12px;
}
body.bubblechat #chat .mes { border-radius: var(--ds-radius-message); }
body.documentstyle #chat .mes { border-radius: 3px; outline: none; }
body.hideChatAvatars #chat .mes { padding-inline: 18px; }
body.noShadows #chat .mes { box-shadow: none; }

/* Header wrapping preserves all controls when names are long. */
#chat .mes .ch_name > .name_text { min-width: 0; white-space: normal; }
#chat .mes .mes_edit_buttons { opacity: 1; filter: none; flex-wrap: wrap; }
/* VERIFY: .mes_edit_cancel/.mes_edit_done verified in public/style.css. */
#chat .mes .mes_edit_cancel.menu_button { background-color: var(--SmartThemeBlurTintColor); border-color: var(--ds-error); }
#chat .mes .mes_edit_done.menu_button { background-color: var(--SmartThemeBlurTintColor); border-color: var(--ds-success); }

/* 5. RP markup. Distinctions survive grayscale: weight/style/decoration. */
#chat .mes .mes_text {
    font-family: var(--ds-reading-font);
    font-weight: 400;
    font-size: max(15px, calc(var(--mainFontSize) * 1.13));
    line-height: 1.65;
    max-width: 72ch;
    min-width: 0;
    color: var(--SmartThemeBodyColor);
    overflow-wrap: anywhere;
    padding-block: 5px;
}
#chat .mes .mes_text p { margin-block: .35em 1em; }
#chat .mes .mes_text :is(em, i) { color: var(--SmartThemeEmColor); font-style: italic; }
#chat .mes .mes_text strong { color: var(--SmartThemeBodyColor); font-weight: 700; }
#chat .mes .mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-style: normal;
}
#chat .mes .mes_text q::before, #chat .mes .mes_text q::after { content: ''; }
#chat .mes .mes_text q em { color: var(--SmartThemeQuoteColor); font-style: italic; }
#chat .mes .mes_text u {
    color: var(--SmartThemeUnderlineColor);
    text-decoration-style: double;
    text-underline-offset: .2em;
}
#chat .mes .mes_text blockquote {
    border-inline-start: 3px solid var(--SmartThemeQuoteColor);
    margin-inline: 0;
    padding: .65em 1em;
    color: var(--SmartThemeBodyColor);
    background: rgba(11,10,18,.3);
    border-radius: 0 6px 6px 0;
}
#chat .mes .mes_text code {
    font-family: var(--monoFontFamily);
    font-size: .92em;
    color: var(--SmartThemeBodyColor);
    background: rgba(11,10,18,.7);
    padding: .12em .3em;
    border-radius: 4px;
    overflow-wrap: anywhere;
}
#chat .mes .mes_text pre {
    max-width: 100%;
    overflow-x: auto;
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: var(--ds-radius-field);
    background: var(--ds-bg);
    padding: 14px;
    scrollbar-width: thin;
}
#chat .mes .mes_text pre code {
    display: block;
    padding: 0;
    background: transparent;
    white-space: pre;
    line-height: 1.6;
    overflow-wrap: normal;
    color: var(--SmartThemeBodyColor);
}
/* VERIFY: syntax highlighters add spans outside the supplied DOM map.
   Verified local ST uses highlight.js. Inherit readable monochrome code. */
/* v2.1: highlight.js span colours are kept */
#chat .mes .mes_text hr {
    border: 0;
    height: 20px;
    background: var(--ds-clock) center / 120px 18px no-repeat;
    margin-block: 1.4em;
}
#chat .mes .mes_text :is(ul, ol) { padding-inline-start: 1.5em; }
#chat .mes .mes_text li { margin-block: .3em; }
#chat .mes .mes_text img, #chat .mes .mes_media_wrapper { max-width: 100%; }
/* Reasoning: a page from the witch's book. Gold-framed plum card, Prata title, thoughts in muted italic.
   The divider ornament under the title is painted by the extension (frames.css). */
#chat .mes .mes_reasoning_details {
    max-width: 72ch;
    margin: 10px 0;
    border: 1px solid rgba(217,178,111,.28);
    border-radius: 10px;
    background: linear-gradient(180deg, rgba(36,24,46,.92), rgba(20,15,30,.92));
    box-shadow: inset 0 0 0 1px rgba(168,139,255,.07), 0 3px 14px rgba(0,0,0,.4);
    padding: 0;
    overflow: hidden;
    color: var(--SmartThemeBodyColor);
}
/* ST offsets the block by --mes-right-spacing and pulls the summary back out by the same amount;
   with the theme's border that pushed the header past the frame. */
#chat .mes .mes_reasoning_details, #chat .mes .mes_reasoning_details .mes_reasoning_summary { margin-right: 0; }
#chat .mes .mes_reasoning_summary { cursor: pointer; min-height: 28px; }
#chat .mes .mes_reasoning_header {
    margin: 0;
    padding: 9px 14px;
    padding-right: calc(.7em + 30px);
    border-radius: 0;
    background: transparent;
    transition: background-color var(--ds-t-s) var(--ds-ease-out);
}
#chat .mes .mes_reasoning_header_title {
    font-family: var(--ds-title-font);
    font-weight: 400;
    font-size: 1.02em;
    letter-spacing: .03em;
    line-height: 1.3;
    color: var(--ds-gold);
}
#chat .mes .mes_reasoning_details[data-has-content="true"] .mes_reasoning_header:hover { background-color: rgba(217,178,111,.08); }
/* Header and its actions share one row; the title gives way first. */
#chat .mes .mes_reasoning_details .mes_reasoning_summary { flex-wrap: nowrap; align-items: center; gap: 0; }
#chat .mes .mes_reasoning_header_block { flex: 1 1 auto; min-width: 0; }
/* Open on a narrow screen: the actions drop below the title instead of squeezing it. */
#chat .mes .mes_reasoning_details[open] .mes_reasoning_summary { flex-wrap: wrap; }
#chat .mes .mes_reasoning_details[open] .mes_reasoning_header_block { flex: 1 1 14em; }
#chat .mes .mes_reasoning_details[open] .mes_reasoning_actions { margin-left: auto; }
#chat .mes .mes_reasoning_header { width: 100%; box-sizing: border-box; min-width: 0; }
#chat .mes .mes_reasoning_header_title { min-width: 0; overflow-wrap: anywhere; }
#chat .mes .mes_reasoning_actions { flex: 0 0 auto; flex-wrap: nowrap; gap: 0; padding-right: 4px; }
#chat .mes .mes_reasoning_details[open] .mes_reasoning_summary { padding-bottom: 10px; }
#chat .mes .mes_reasoning {
    color: #cdbff0;
    font-family: var(--ds-reading-font);
    font-style: italic;
    font-size: max(15px, var(--mainFontSize));
    line-height: 1.75;
    margin: 0;
    padding: 10px 20px 16px;
    border-left: 0;
    overflow-wrap: anywhere;
}

/* 6. swipes. No transforms or animation on ST's native sliding blocks. */
#chat .mes :is(.swipe_left, .swipe_right) {
    opacity: 1;
    color: var(--ds-lavender);
    min-width: 40px;
    min-height: 40px;
    border-radius: 50%;
    transition: transform var(--ds-t-xs) var(--ds-ease-out);
}
#chat .mes :is(.swipe_left, .swipe_right):hover { transform: translateY(-1px); color: var(--SmartThemeBodyColor); }
#chat .mes .swipes-counter {
    position: relative;
    opacity: 1;
    min-width: 44px;
    min-height: 44px;
    padding: 12px 7px;
    line-height: 20px;
    text-align: center;
    box-sizing: border-box;
    border-radius: 50%;
    color: var(--ds-pink);
    background-color: var(--SmartThemeBlurTintColor);
    font-family: var(--monoFontFamily);
    font-size: 12px;
}
#chat .mes .swipes-counter::before {
    content: '';
    position: absolute;
    inset: 2px;
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: 50%;
    background: repeating-conic-gradient(from 0deg, transparent 0deg 28deg, rgba(217,178,111,.7) 28deg 30deg);
    mask: radial-gradient(circle, transparent 62%, #000 65%);
    pointer-events: none;
}
#chat .mes .swipes-counter::after {
    content: '';
    position: absolute;
    inset: 4px;
    border-radius: 50%;
    background: linear-gradient(var(--ds-gold), var(--ds-gold)) center 1px / 1px 6px no-repeat;
    pointer-events: none;
    transform-origin: center;
}
body.swipeAllMessages #chat .mes:not(.last_mes) .swipes-counter { color: var(--ds-pink); opacity: 1; }
/* The extension paints the ImageGen rewind strip; the dial turn stays independent. */
#chat .mes.last_mes.ds-rewinding .swipes-counter::after {
    animation: ds-rewind-hand 500ms var(--ds-ease-rewind);
}

/* Reserve a bottom rail so the larger dial never covers prose. */
#chat .mes.last_mes:not(.smallSysMes, [is_user="true"]),
body.swipeAllMessages #chat .mes:not(.smallSysMes, [is_user="true"]) { padding-bottom: 86px; }
/* !important: ST toggle-dependent.css forces 20px for hideChatAvatars; the swipe dial rail needs 86px */
body.hideChatAvatars #chat .mes.last_mes:not(.smallSysMes, [is_user="true"]) { padding-bottom: 86px !important; }
#chat .mes .swipe_left { bottom: 50px; }
/* The welcome message cannot be swiped: ST hides the dial there, but the theme forces opacity: 1. */
#chat .mes:is([type="assistant_message"], [type="welcome_prompt"]) :is(.swipe_left, .swipe_right, .swipes-counter) { display: none; }

/* 7. input. ST retains ownership of every send/stop button's display. */
#send_form {
    position: relative;
    background-color: var(--SmartThemeBlurTintColor);
    background-image: var(--ds-grain);
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: var(--ds-radius-panel);
    outline: 1px solid var(--ds-gold-rule);
    outline-offset: -4px;
