@media screen and (max-width: 1000px) and (orientation: portrait) {
    /* !important: ST sets an inline background-image; this mobile override
       intentionally disables the Backgrounds picker in portrait mode. */
    #bg1 { background-image: url('backgrounds/aishiteru_bg_mobile.webp') !important; background-size: cover !important; background-position: center top !important; }
}
@media screen and (max-width: 768px) {
    /* !important: an enabled optional switch must not restore phone motion. */
    #bg1::before, #bg1::after { animation: none !important; will-change: auto; }
    #chat .mes .mes_text { max-width: 100%; }
    #send_form { flex-wrap: wrap; }
    .drawer-content input[type='range'] { height: 36px; }
    .drawer-content select { min-height: 40px; }
    .drawer-content label:has(> input:is([type='checkbox'], [type='radio'])) { min-height: 40px; display: flex; align-items: center; gap: 8px; }
    #send_textarea { flex: 1 1 55%; max-width: 100%; }
    #rightSendForm { flex-wrap: wrap; justify-content: flex-end; }
    .popup .popup-content { max-width: 100%; }
    body #toast-container { max-width: calc(100vw - 20px); }
}
@media screen and (max-width: 450px) {
    /* Compact phone composer: controls and input share a row; typed text alone grows it. */
    #send_form { padding:5px; border-radius:14px; outline-color:rgba(217,178,111,.08); }
    #send_form #nonQRFormItems { display:grid; grid-template-columns:auto minmax(45%,1fr) auto; align-items:center; gap:2px; }
    #send_form #leftSendForm { grid-column:1; width:auto; gap:0; min-width:0; flex-wrap:wrap; }
    #send_form #send_textarea { grid-column:2; width:100%; min-height:40px; max-height:min(160px,28dvh); padding:8px 4px; margin:0; box-sizing:border-box; font-size:max(16px,calc(var(--mainFontSize) * 1.05)); line-height:1.4; }
    #send_form #send_textarea::placeholder { font-family:var(--mainFontFamily); font-size:.82em; }
    #send_form #rightSendForm, #send_form.compact #rightSendForm { grid-column:3; width:auto; flex-basis:auto; flex-wrap:wrap; justify-content:flex-end; min-width:0; gap:0; }
    #send_form :is(#options_button,#extensionsMenuButton,#send_but,#mes_stop) { font-size:22px; }
    #send_form::after { background-size:160px 30px; }
    #send_form:focus-within::after { opacity:.18; }
    /* The mobile artwork is visible between cards; the reading column stays dark. */
    #chat { background:transparent; padding-inline:10px; }
    #chat .mes { background-color:rgba(26,23,38,.88); margin-block:12px; }
    #chat .mes[is_user="true"] { background-color:rgba(28,26,43,.90); }
    #chat .mes { padding: 12px 8px; }
    #chat .mes .name_text { font-size: 1.15em; }
    #chat .mes .mes_buttons { gap: 0; flex-wrap: wrap; }
    #send_textarea { flex-basis: calc(100% - 56px); }
    #send_form #send_textarea { flex-basis: calc(100% - 56px); }
    #rightSendForm { flex-basis: 100%; }
    #send_form.compact #rightSendForm { flex-basis: 100%; }
    dialog.popup { max-width: calc(100vw - 20px); padding: 16px 12px; box-sizing: border-box; }
}
@media screen and (max-width: 768px) {
    /* Welcome screen: 40px touch targets and wide fonts overflowed ST's single-row header. */
    .welcomePanel { padding: 8px; }
    .welcomePanel .welcomeHeaderTitle { flex-wrap: nowrap; }
    .welcomePanel .welcomeHeaderVersionDisplay { font-size: 1.1em; min-width: 0; overflow-wrap: anywhere; }
    .welcomePanel .welcomeHeader { flex-wrap: wrap; justify-content: space-between; gap: 6px; }
    .welcomePanel .recentChatsTitle { flex: 1 1 auto; white-space: nowrap; font-size: 1.05em; }
    .welcomePanel .welcomeShortcuts { flex: 0 1 auto; justify-content: flex-end; }
    .welcomePanel .welcomeShortcuts .menu_button { min-width: 36px; min-height: 36px; padding: 5px 8px; margin: 0; }
    /* The welcome message has no swipes: do not reserve their 86px. */
    #chat .mes.last_mes[type="assistant_message"] { padding-bottom: 14px; }
    body.hideChatAvatars #chat .mes.last_mes[type="assistant_message"] { padding-bottom: 14px !important; }
}
/* 15. Welcome screen: recent chats as compact cards in the message style.
   Name and date on top, last message below, stats and quiet actions share the bottom row. */
.welcomeRecent .recentChatList { gap: 8px; }
.welcomeRecent .recentChatList .recentChat {
    align-items: flex-start;
    gap: 12px;
    padding: 14px 18px; /* clears the frame's corner hands, as on messages */
    background-color: rgba(26,23,38,.82);
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: var(--ds-radius-message);
    transition: background-color var(--ds-t-s) var(--ds-ease-out), border-color var(--ds-t-s) var(--ds-ease-out);
}
.welcomeRecent .recentChatList .recentChat:hover { background-color: rgba(38,32,58,.9); border-color: var(--ds-lavender); }
.welcomeRecent .recentChatList .recentChat .recentChatInfo {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "name date" "msg msg" "stats actions";
    column-gap: 8px;
    row-gap: 2px;
    min-width: 0;
    align-self: stretch;
}
.welcomeRecent .recentChatList .recentChat :is(.chatNameContainer, .chatMessageContainer) { display: contents; }
.welcomeRecent .recentChatList .recentChat .chatName { grid-area: name; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; align-self: center; }
.welcomeRecent .recentChatList .recentChat .chatName .characterName { font-family: var(--ds-title-font); font-weight: 400; font-size: 1.1em; color: var(--ds-gold); }
.welcomeRecent .recentChatList .recentChat .chatName > span { color: var(--ds-muted); font-size: .85em; }
.welcomeRecent .recentChatList .recentChat .chatDate { grid-area: date; align-self: center; color: var(--ds-muted); white-space: nowrap; }
.welcomeRecent .recentChatList .recentChat .chatMessage { grid-area: msg; font-family: var(--ds-reading-font); opacity: .85; }
.welcomeRecent .recentChatList .recentChat .chatStats { grid-area: stats; align-self: center; display: flex; align-items: center; gap: 8px; color: var(--ds-muted); }
.welcomeRecent .recentChatList .recentChat .chatActions { grid-area: actions; align-self: center; gap: 2px; justify-content: flex-end; }
body .welcomeRecent .recentChatList .recentChat .chatActions button {
    min-width: 32px;
    min-height: 32px;
    margin: 0;
    padding: 4px;
    background: transparent;
    border: 0;
    box-shadow: none;
    color: var(--ds-muted);
}
body .welcomeRecent .recentChatList .recentChat .chatActions button:is(:hover, :focus-visible) { color: var(--ds-lavender-hi); background: var(--ds-lavender-lo); }
body .welcomeRecent .recentChatList .recentChat .chatActions .deleteChat:is(:hover, :focus-visible) { color: var(--ds-crimson-text); background: var(--ds-crimson-lo); }
@media (hover: none) {
    body .welcomeRecent .recentChatList .recentChat .chatActions button { min-width: 40px; min-height: 40px; }
}
@media (max-width: 450px) { .welcomeRecent .recentChatList .recentChat { padding: 10px 12px; gap: 10px; } }
/* 16. Third-party top-bar icons (Horae etc.) keep their Font Awesome glyph, tinted to the theme. */
#top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon { color: var(--ds-lavender-hi); filter: drop-shadow(0 0 3px rgba(168,139,255,.35)); }
#top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon.openIcon { color: var(--ds-gold); }
/* Compatibility: "Chat Top Bar" extension (#extensionTopBar). It has a fixed-height, wrapping row;
   the touch rule below gives its icons min 40px (ST adds .interactable), so they wrapped and
   spilled under the top bar. Keep its icons compact and let the row grow instead. */
body #extensionTopBar {
    height: auto;
    min-height: var(--bottomFormBlockSize);
    flex-wrap: nowrap;
    align-items: center;
    gap: 4px;
    padding: 2px 6px;
    box-sizing: border-box;
}
body #extensionTopBar > :is(i, .interactable) {
    min-width: 32px;
    min-height: 32px;
    padding: 0;
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
}
body #extensionTopBar :is(#extensionTopBarChatName, #extensionTopBarSearchInput) {
    min-width: 0;
    flex: 1 1 60px;
    width: auto;
    padding-block: 4px;
}
/* Compatibility: Manage extensions popup. Long (e.g. Russian) toolbar labels must wrap, not overlap,
   even when another extension forces white-space: nowrap on .menu_button. */
body .extensions_toolbar { flex-wrap: wrap; }
body .extensions_toolbar > .menu_button { white-space: normal; flex: 1 1 auto; text-align: center; min-width: 0; }
@media screen and (max-width: 1000px) and (orientation: landscape) {
    .drawer-content { max-height: 88dvh; overflow-y: auto; }
    #send_textarea { max-height: 28dvh; }
    dialog.popup { max-height: 90dvh; }
}
@media (hover: none) {
    #chat .mes .mes_buttons { opacity: 1; }
    #chat .mes :is(.mes_button, .mes_edit, .extraMesButtonsHint, .mes_edit_buttons > *) { min-width: 40px; min-height: 40px; padding: 10px; box-sizing: border-box; }
    /* 40px targets don't fit 9+ actions in one row; ST's nowrap + overflow:hidden then hides the first ones. Wrap instead. */
    #chat .mes .extraMesButtons { flex-wrap: wrap; justify-content: flex-end; gap: 0; }
    body .menu_button, body .interactable, .popup .popup-controls > *, .drawer-content .inline-drawer-toggle { min-width: 40px; min-height: 40px; box-sizing: border-box; }
    body :is(.menu_button, .drawer-icon, .swipe_left, .swipe_right, #send_but, #mes_continue, #mes_impersonate, #options_button):hover { transform: none; }
}
